#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Begin transaction for safety
  sqlgen::begin_transaction(conn);

  // Delete users who have not logged in since 2025-01-01
  // Using the where clause to filter users with last_login < '2025-01-01'
  sqlgen::delete_from<User> | 
    sqlgen::where("last_login"_c < sqlgen::DateTime("2025-01-01")) | 
    conn;

  // Commit the transaction and return the result
  auto result = sqlgen::commit(conn);

  return result;
}

} // namespace delete_inactive_users

