        rfl::Field<"SNo", std::string>,
        Student,
        rfl::Field<"SNo", std::string>
      >,
      sqlgen::ForeignKey<
        rfl::Field<"CID", int>,
        Course,
        rfl::Field<"CID", int>
      >
