Looking at the requirements and the reference code, I need to:

1. Connect to SQLite database "test_db.sqlite"
2. Create User and Post tables
3. Query for users who posted between 2025-12-01 and 2025-12-31
4. Return the results as a vector of ActiveUser

Here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <chrono>
#include <iomanip>
#include <sstream>

namespace query_active_users_posts {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

std::vector<ActiveUser> query_active_users_posts() {
    using namespace sqlgen::literals;

    // 1. Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // 2. Create User and Post tables
    conn.execute(sqlgen::create_table<User>);
    conn.execute(sqlgen::create_table<Post>);

    // 3. Query users who have created at least one post between 2025-12-01 and 2025-12-31
    // Create the date range conditions
    auto start_date = sqlgen::DateTime("2025-12-01");
    auto end_date = sqlgen::DateTime("2025-12-31");

    // Build the query using JOIN and WHERE
    auto query = sqlgen::select_from<User, "u">("u"_c / "user_id", "u"_c / "username")
                 | sqlgen::join<Post, "p">("u"_c / "user_id" == "p"_c / "user_id")
                 | sqlgen::where(("p"_c / "created_at" >= start_date) && 
                                ("p"_c / "created_at" <= end_date))
                 | sqlgen::to<ActiveUser>;

    // Execute the query and return results
    auto result = conn.execute(query);

    if (result) {
        return std::move(result.value());
    }

    // Return empty vector if query fails
    return std::vector<ActiveUser>();
}

}  // namespace query_active_users_posts
```

