1. Connect to SQLite database "test_db.sqlite"
2. Create Course and Enrollment tables
3. Query with a LEFT JOIN to get enrollment statistics per course
4. Return results as a vector of CourseStats

Based on the reference code and the SQL statement provided, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  // View to store course enrollment statistics
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  using namespace sqlgen;

  // 1. Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // 2. Create tables
  conn.run(create_table<Course>);
  conn.run(create_table<Enrollment>);

  // 3. Query the database
  // Define table aliases for the query
  using C = Course;
  using E = Enrollment;

  // Build the query following the reference SQL:
  // SELECT c.title, COUNT(e.enrollment_id) as student_count, AVG(e.grade) as avg_grade
  // FROM Course c
  // LEFT JOIN Enrollment e ON c.course_id = e.course_id
  // GROUP BY c.course_id, c.title;

  auto query = select_from<C, "c">(
                 "c"_c / "title"_c,
                 count("e"_c / "enrollment_id"_c) | as<"student_count">,
                 avg("e"_c / "grade"_c) | as<"avg_grade">
               )
               | left_join<E, "e">("c"_c / "course_id"_c == "e"_c / "course_id"_c)
               | group_by("c"_c / "course_id"_c, "c"_c / "title"_c)
               | to<CourseStats>;

  // 4. Execute query and return results as vector
  auto result_range = conn.run(query);
  return internal::collect::vector(result_range);
}

}  // namespace query_course_enrollment_stats
```

