struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    using namespace sqlgen;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Start with a base SELECT query
    auto query = select_from<Book>();

    // Build dynamic WHERE conditions based on provided filters
    std::optional<decltype(where("title"_c.like("")))> combined_condition;

    // Add title LIKE condition if title_keyword is provided
    if (filters.title_keyword.has_value()) {
        auto title_condition = where("title"_c.like("%" + filters.title_keyword.value() + "%"));
        combined_condition = title_condition;
    }

    // Add year >= condition if min_year is provided
    if (filters.min_year.has_value()) {
        auto year_condition = where("year"_c >= filters.min_year.value());
        if (combined_condition.has_value()) {
            combined_condition = where(combined_condition.value().condition && year_condition.condition);
        } else {
            combined_condition = year_condition;
        }
    }

    // Add genre = condition if genre is provided
    if (filters.genre.has_value()) {
        auto genre_condition = where("genre"_c == filters.genre.value());
        if (combined_condition.has_value()) {
            combined_condition = where(combined_condition.value().condition && genre_condition.condition);
        } else {
            combined_condition = genre_condition;
        }
    }

    // Add price <= condition if max_price is provided
    if (filters.max_price.has_value()) {
        auto price_condition = where("price"_c <= filters.max_price.value());
        if (combined_condition.has_value()) {
            combined_condition = where(combined_condition.value().condition && price_condition.condition);
        } else {
            combined_condition = price_condition;
        }
    }

    // Execute the query with or without WHERE clause
    std::vector<Book> results;
    if (combined_condition.has_value()) {
        auto final_query = query | combined_condition.value() | to<Book>;
        for (const auto& book : conn.execute(final_query)) {
            results.push_back(book);
        }
    } else {
        auto final_query = query | to<Book>;
        for (const auto& book : conn.execute(final_query)) {
            results.push_back(book);
        }
    }

    return results;
}

}  // namespace query_search_books_by_criteria
