      conn.execute(idx_sku);

      // 4. Create composite index on (name, price)
      conn.execute(
        sqlgen::create_index<"idx_product_name_price", Product>("name"_c, "price"_c) 
        | sqlgen::if_not_exists
      );

      return true;
    } catch (const std::exception& e) {
      // Handle any exceptions during index creation
      return false;
    }
  }

}  // namespace schema_manage_indexes

