  sqlgen::exec(conn, "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20)");

  // Try to add is_active column with default value
  // If column already exists, this will error but we handle it gracefully
  sqlgen::exec(conn, "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1");

