```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    // Return true if no IDs provided (nothing to delete)
    if (ids.empty()) {
        return true;
    }

    try {
        // Connect to the SQLite database
        auto conn = sqlgen::sqlite::connect("test_db.sqlite");

        // Use literals for column references
        using namespace sqlgen::literals;

        // Create the update statement
        // Set is_deleted to 1 and deleted_at to current timestamp
        auto update_stmt = sqlgen::update<Document>(
            "is_deleted"_c = 1,
            "deleted_at"_c = sqlgen::DateTime::now()
        ) | sqlgen::where("doc_id"_c.in(ids));

        // Execute the update statement
        conn->execute(update_stmt);

        return true;
    } catch (const std::exception& e) {
        // Log error if needed: e.what()
        return false;
    }
}

}  // namespace soft_delete_records
```

