```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_order_status {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string status;
  sqlgen::DateTime order_date;
  double total_amount;
};

int update_order_status() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  int total_affected = 0;

  // 1. Update status of 'pending' orders older than 7 days to 'expired'
  auto update1 = sqlgen::update<Order>(
    "status"_c.set("expired")
  ) | sqlgen::where(
    "status"_c == "pending" && 
    "order_date"_c < sqlgen::Func<"DATE", std::string>("now", "-7 days")
  );

  auto result1 = update1(conn);
  total_affected += result1.num_rows_affected();

  // 2. Update status of 'shipped' orders to 'delivered'
  // (simulating delivery confirmation received)
  auto update2 = sqlgen::update<Order>(
    "status"_c.set("delivered")
  ) | sqlgen::where(
    "status"_c == "shipped"
  );

  auto result2 = update2(conn);
  total_affected += result2.num_rows_affected();

  // Commit the changes
  sqlgen::commit(conn);

  // Return the total number of rows affected
  return total_affected;
}

} // namespace update_order_status
```

