1. Connects to SQLite database "test_db.sqlite"
2. Inserts Event data into a table
3. Performs temporal analysis using SQL date/time functions
4. Returns the results as TemporalAnalysis records

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  using namespace sqlgen;
  using namespace rfl::literal;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Create the Event table and insert data
  execute(drop_table<Event>, conn);
  execute(create_table<Event>, conn);
  execute(insert(events), conn);

  // Build the SELECT query with temporal operations
  auto query = select(
    "event_id"_c = field<"event_id", Event>,
    "event_name"_c = field<"event_name", Event>,
    "start_day"_c = day(field<"start_time", Event>),
    "start_month"_c = month(field<"start_time", Event>),
    "start_year"_c = year(field<"start_time", Event>),
    "start_hour"_c = hour(field<"start_time", Event>),
    "start_minute"_c = minute(field<"start_time", Event>),
    "start_second"_c = second(field<"start_time", Event>),
    "start_weekday"_c = weekday(field<"start_time", Event>),
    "start_epoch"_c = unixepoch(field<"start_time", Event>),
    "duration_days"_c = days_between(field<"start_time", Event>, field<"end_time", Event>)
  ).from<Event>()
   .where(field<"end_time", Event>.is_not_null());

  // Execute the query and return results
  auto result = execute(query | read<std::vector<TemporalAnalysis>>, conn);

  if (result) {
    return std::move(result.value());
  }

  // Return empty vector if query fails
  return std::vector<TemporalAnalysis>{};
}

}  // namespace analyze_temporal_data
```

Key implementation details:

1. **Database Connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the specified database file.

2. **Table Setup**: Creates the Event table using `create_table<Event>` and inserts the provided events.

3. **Temporal Operations**: Uses the sqlgen operations functions:
   - `day()`, `month()`, `year()` for date components
   - `hour()`, `minute()`, `second()` for time components
   - `weekday()` for day of week
   - `unixepoch()` for Unix timestamp
   - `days_between()` for duration calculation

4. **Field Access**: Uses `field<"field_name", Event>` to reference table columns in the query.

5. **WHERE Clause**: Filters for events where `end_time IS NOT NULL` using `.where(field<"end_time", Event>.is_not_null())`.

6. **Query Execution**: Executes the query with `read<std::vector<TemporalAnalysis>>` to populate the result structure.

