      )
  )");

  // Collect results
  std::vector<FriendConnection> results;

  // Execute mutual friends query and collect results
  auto mutual_friends_results = mutual_friends_query.execute();
  for (const auto& row : mutual_friends_results) {
    FriendConnection conn;
    conn.user1_name = row.get<std::string>("user1_name");
    conn.user2_name = row.get<std::string>("user2_name");
