  auto gross_total = unit_price * quantity;

  // discounted_total = unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)
  auto discount_multiplier = 1.0 - (coalesce(discount_rate, 0.0) / 100.0);
  auto discounted_total = unit_price * quantity * discount_multiplier;

  // final_total = discounted_total * (1 + COALESCE(tax_rate, 0)/100)
  auto tax_multiplier = 1.0 + (coalesce(tax_rate, 0.0) / 100.0);
  auto final_total = unit_price * quantity * discount_multiplier * tax_multiplier;

  // unit_cost = unit_price * quantity / quantity (simplified to unit_price)
  auto unit_cost = (unit_price * quantity) / quantity;

  // quantity_group = quantity % 10
  auto quantity_group = quantity % 10;

  // estimated_profit = unit_price * 0.3
  auto estimated_profit = unit_price * 0.3;

  // Perform the query
  auto result = conn
    | select(
        as<"item_id">(item_id),
        as<"order_id">(order_id),
        as<"product_id">(product_id),
        as<"unit_price">(unit_price),
        as<"quantity">(quantity),
        as<"discount_rate">(coalesce(discount_rate, 0.0)),
