1. Connect to the SQLite database "test_db.sqlite"
2. Use the `replace` function to replace text in the `content` column
3. Use the `update` function to update the Notes table
4. Read and return the updated notes

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace replace_text_in_notes {

struct Note {
  sqlgen::PrimaryKey<int> note_id;
  std::string content;
};

struct UpdatedNote {
  sqlgen::PrimaryKey<int> note_id;
  std::string updated_content;
};

/**
 * description: replace_text_in_notes.
 * This function demonstrates how to replace text in notes using sqlgen update API.
 * It replaces all occurrences of "foo" with "bar" in the content column of the Note table.
 * Returns: std::vector<UpdatedNote>.
 */
std::vector<UpdatedNote> replace_text_in_notes() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Use the literal operator to reference the content column
  using namespace sqlgen::literals;

  // Update the Notes table by replacing "foo" with "bar" in the content column
  // The replace function takes: (column/string, from_text, to_text)
  auto update_query = sqlgen::update<Note>(
    "content"_c.set(sqlgen::replace("content"_c, "foo", "bar"))
  );

  // Execute the update
  update_query(conn);

  // Read all updated notes and return them
  auto read_query = sqlgen::read<std::vector<UpdatedNote>>;
  auto result = read_query(conn);

  // Extract the vector from the result
  if (result) {
    return std::move(*result);
  }

  // Return empty vector if there was an error
  return std::vector<UpdatedNote>();
}

}  // namespace replace_text_in_notes
```

