#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // 1. Create Account table
    sqlgen::write(conn, sqlgen::create_table<Account>);

    // Insert some test data
    std::vector<Account> accounts = {
      {.account_id = 1, .balance = 1000.0, .status = "active"},
      {.account_id = 2, .balance = 2000.0, .status = "active"},
      {.account_id = 3, .balance = 1500.0, .status = "inactive"}
    };

    for (const auto& account : accounts) {
      sqlgen::write(conn, sqlgen::Write{std::vector<Account>{account}});
    }

    // 2. Update balances and statuses using set(...)
    using namespace sqlgen::literals;

    // Update balance for account_id = 1
    auto update1 = sqlgen::update<Account>(
      "balance"_c.set(1500.0)
    ) | sqlgen::where("account_id"_c == 1);
    sqlgen::write(conn, update1);

    // Update status for account_id = 2
    auto update2 = sqlgen::update<Account>(
      "status"_c.set("inactive")
    ) | sqlgen::where("account_id"_c == 2);
    sqlgen::write(conn, update2);

    // Update both balance and status for account_id = 3
    auto update3 = sqlgen::update<Account>(
      "balance"_c.set(3000.0),
      "status"_c.set("active")
    ) | sqlgen::where("account_id"_c == 3);
    sqlgen::write(conn, update3);

    // 3. Verify changes persisted
    auto result1 = sqlgen::read<Account>(
      conn, 
      sqlgen::select_all | sqlgen::where("account_id"_c == 1)
    );
    if (result1.empty() || result1[0].balance != 1500.0) {
      return false;
    }

    auto result2 = sqlgen::read<Account>(
      conn, 
      sqlgen::select_all | sqlgen::where("account_id"_c == 2)
    );
    if (result2.empty() || result2[0].status != "inactive") {
      return false;
    }

    auto result3 = sqlgen::read<Account>(
      conn, 
      sqlgen::select_all | sqlgen::where("account_id"_c == 3)
    );
    if (result3.empty() || result3[0].balance != 3000.0 || result3[0].status != "active") {
      return false;
    }

    return true;
  } catch (const std::exception& e) {
    return false;
  }
}

}  // namespace update_set_operations
