/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  auto db = sqlgen::sqlite::open("test_db.sqlite");

  // Define table references
  auto product_table = sqlgen::table<Product>(db, "Product");
  auto sales_table = sqlgen::table<Sales>(db, "Sales");

  // Build the query
  auto query = sqlgen::select(
    product_table.product_id,
    product_table.product_name,
    product_table.category,
    sqlgen::sum(product_table.price * sales_table.quantity).as("total_sales")
  )
  .from(product_table)
  .inner_join(sales_table)
  .on(product_table.product_id == sales_table.product_id)
  .group_by(
    product_table.product_id,
    product_table.product_name,
    product_table.category
  )
  .order_by(sqlgen::desc("total_sales"))
  .limit(limit_count);

  // Execute the query and retrieve results
  std::vector<TopProduct> results;

  for (auto row : query.execute()) {
    TopProduct top_product;
    top_product.product_id = row.get<int>(0);
    top_product.product_name = row.get<std::string>(1);
    top_product.category = row.get<std::string>(2);
    top_product.total_sales = row.get<double>(3);
    results.push_back(top_product);
  }

  return results;
}

}  // namespace get_top_products
