  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: This function demonstrates creating a view.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Create column references for the query
    auto o_order_id = "o"_c / "order_id"_c;
    auto o_customer = "o"_c / "customer"_c;
    auto oi_order_id = "oi"_c / "order_id"_c;
    auto oi_unit_price = "oi"_c / "unit_price"_c;
    auto oi_quantity = "oi"_c / "quantity"_c;

    // Build the SELECT query with JOIN and aggregation
    auto query = select_from<Order, "o">(
        o_order_id,
        o_customer,
        sum(oi_unit_price * oi_quantity).as<"total"_n>()
    ) | inner_join<OrderItem, "oi">(on(o_order_id == oi_order_id))
      | group_by(o_order_id, o_customer);

    // Create the view using CREATE VIEW AS
    auto create_view_stmt = create_as<OrderSummary>(query);
    conn->run(create_view_stmt);

    // Read from the view to verify data
    auto results = conn->read<OrderSummary>();

    // Collect results into a vector
    return internal::collect::vector(results);
}

}  // namespace create_view_order_summary
