2. Query Project and TimeLog tables with temporal operations
3. Extract date/time components and compute days between timestamps
4. Return the results as a vector of TimeMetrics

Based on the reference code and the SQL statement provided, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Define column references using literals
  using namespace sqlgen::literals;

  // Build the query
  auto query = select_from<Project, "p">(
    "p"_c["project_id"],
    "p"_c["name"],
    day("t"_c["start_time"]) | as<"day">,
    month("t"_c["start_time"]) | as<"month">,
    year("t"_c["start_time"]) | as<"year">,
    hour("t"_c["start_time"]) | as<"hour">,
    minute("t"_c["start_time"]) | as<"minute">,
    second("t"_c["start_time"]) | as<"second">,
    days_between("t"_c["start_time"], "t"_c["end_time"]) | as<"duration_days">
  ) 
  | inner_join<TimeLog, "t">(
      "p"_c["project_id"] == "t"_c["project_id"]
  )
  | to<TimeMetrics>;

  // Execute query and collect results
  auto result_range = conn.run(query);

  return internal::collect::vector(result_range);
}

}  // namespace project_time_tracking
```

